          gvcd.Guid,
          gvcd.Name,
          gvcd.ColumnOrder,
          gvcd.GridViewDefinitionId,
          gvcd.IsPrimaryKey,
          gvcd.IsHidden,
          gvcd.IsFiltered,
          gvcd.IsCombo,
          gvcd.IsLongitude,
          gvcd.IsLatitude,
          gvcd.DisplayFormat,
          gvcd.Width,
          ll.Guid AS LanguageLabelGuid
  FROM
          SUserInterface.GridViewColumnDefinitions gvcd
